=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters.
// Implements interface_spec.md and microarchitecture.md (rr_arbiter fixture).
// One state register: the priority pointer ptr. grant is combinational.
module rr_arbiter #(
  parameter integer N = 4
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire [N-1:0] req,
  output reg  [N-1:0] grant
);
  localparam integer PW   = (N > 1) ? $clog2(N) : 1;
  localparam integer LAST = N - 1;

  reg [PW-1:0] ptr;
  reg [PW-1:0] ptr_next;
  reg [PW-1:0] winner;
  reg [PW-1:0] idx;
  reg          found;
  integer      i;

  // Grant logic: walk from ptr upwards, wrapping at LAST (not at a power of two).
  always @* begin
    grant  = {N{1'b0}};
    winner = {PW{1'b0}};
    found  = 1'b0;
    idx    = ptr;
    for (i = 0; i < N; i = i + 1) begin
      if (!found && req[idx]) begin
        found      = 1'b1;
        winner     = idx;
        grant[idx] = 1'b1;
      end
      if ({{(32-PW){1'b0}}, idx} == LAST) idx = {PW{1'b0}};
      else                                idx = idx + 1'b1;
    end
  end

  // Pointer update: one past the winner on a grant, otherwise hold.
  always @* begin
    ptr_next = ptr;
    if (found) begin
      if ({{(32-PW){1'b0}}, winner} == LAST) ptr_next = {PW{1'b0}};
      else                                   ptr_next = winner + 1'b1;
    end
  end

  // State register: synchronous active-low reset to 0.
  always @(posedge clk) begin
    if (!rst_n) ptr <= {PW{1'b0}};
    else        ptr <= ptr_next;
  end

`ifdef FORMAL
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  // Reset is active in the first cycle.
  always @(*) begin
    if (!f_past_valid) assume (!rst_n);
  end

  // Independent reference: two-pass masked priority search from ptr.
  reg [N-1:0] f_exp;
  reg         f_hit;
  integer     fi;
  always @(*) begin
    f_exp = {N{1'b0}};
    f_hit = 1'b0;
    for (fi = 0; fi < N; fi = fi + 1) begin
      if (!f_hit && req[fi] && (fi >= ptr)) begin
        f_exp[fi] = 1'b1;
        f_hit     = 1'b1;
      end
    end
    for (fi = 0; fi < N; fi = fi + 1) begin
      if (!f_hit && req[fi]) begin
        f_exp[fi] = 1'b1;
        f_hit     = 1'b1;
      end
    end
  end

  // Grant properties.
  always @(*) begin
    if (f_past_valid) begin
      assert (ptr <= LAST);
      assert ((grant & (grant - 1'b1)) == {N{1'b0}});
      assert ((grant & ~req) == {N{1'b0}});
      assert ((req != {N{1'b0}}) == (grant != {N{1'b0}}));
      assert (grant == f_exp);
    end
  end

  // Pointer rules: 0 after reset, held with no grant.
  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n))
        assert (ptr == {PW{1'b0}});
      else if ($past(grant) == {N{1'b0}})
        assert (ptr == $past(ptr));
    end
  end

  // Global covers.
  always @(*) begin
    if (f_past_valid) begin
      cover (rst_n && (req == {N{1'b1}}));
      cover (rst_n && (req == {N{1'b0}}));
      cover (!rst_n && (req != {N{1'b0}}));
    end
  end

  always @(posedge clk) begin
    if (f_past_valid && $past(rst_n) && ($past(ptr) == LAST))
      cover (ptr == {PW{1'b0}});
  end

  genvar fj;
  generate
    for (fj = 0; fj < N; fj = fj + 1) begin : g_f
      // Pointer moves to one past the winner.
      always @(posedge clk) begin
        if (f_past_valid && $past(rst_n) && $past(grant[fj]))
          assert (ptr == ((fj == LAST) ? 0 : (fj + 1)));
      end

      // Fairness: cycles waited with the request held and not granted.
      reg  [PW:0] f_wait;
      wire [PW:0] f_dist;
      assign f_dist = (fj >= ptr) ? (fj - ptr) : (fj + N - ptr);

      always @(posedge clk) begin
        if (!rst_n || !req[fj] || grant[fj]) f_wait <= {(PW+1){1'b0}};
        else                                 f_wait <= f_wait + 1'b1;
      end

      always @(*) begin
        if (f_past_valid) begin
          assert ((f_wait + f_dist) <= LAST);
          assert (f_wait <= LAST);
        end
      end

      always @(*) begin
        if (f_past_valid) begin
          cover (rst_n && grant[fj]);
          cover (rst_n && req[fj] && grant[fj] && (f_wait == LAST));
        end
      end
    end
  endgenerate
`endif

endmodule
=== END FILE ===
