// Formal wrapper: proves rr_arbiter at N 4 (power of two) and N 5 (not).
module rr_arbiter_formal (
  input  wire       clk,
  input  wire       rst_n,
  input  wire [3:0] req4,
  input  wire [4:0] req5,
  output wire [3:0] grant4,
  output wire [4:0] grant5
);
  rr_arbiter #(.N(4)) u_n4 (
    .clk   (clk),
    .rst_n (rst_n),
    .req   (req4),
    .grant (grant4)
  );

  rr_arbiter #(.N(5)) u_n5 (
    .clk   (clk),
    .rst_n (rst_n),
    .req   (req5),
    .grant (grant5)
  );
endmodule
