// Self-checking testbench for rr_arbiter: N 4 and N 5 side by side.
module rr_arbiter_tb;
  reg clk = 1'b0;
  always #5 clk = ~clk;

  wire        done4;
  wire        done5;
  wire [31:0] pass4;
  wire [31:0] fail4;
  wire [31:0] pass5;
  wire [31:0] fail5;

  rr_arbiter_tb_unit #(.N(4), .SEED(32'h1A2B3C4D)) u_n4 (
    .clk(clk), .done(done4), .passed(pass4), .failed(fail4));

  rr_arbiter_tb_unit #(.N(5), .SEED(32'h5EED0005)) u_n5 (
    .clk(clk), .done(done5), .passed(pass5), .failed(fail5));

  reg [8*64-1:0] nonce;
  reg [31:0]     passed;
  reg [31:0]     failed;
  integer        cyc;

  initial begin
    nonce = {(8*64){1'b0}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
      nonce = {(8*64){1'b0}};
    cyc = 0;
    while (!(done4 && done5) && (cyc < 20000)) begin
      @(posedge clk);
      cyc = cyc + 1;
    end
    passed = pass4 + pass5;
    failed = fail4 + fail5;
    if (!(done4 && done5)) begin
      $error("rr_arbiter_tb: timeout after %0d cycles", cyc);
      failed = failed + 32'd1;
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule

// One arbiter instance with its own stimulus, reference model and checks.
module rr_arbiter_tb_unit #(
  parameter integer N    = 4,
  parameter [31:0]  SEED = 32'h0000_0001
) (
  input  wire        clk,
  output wire        done,
  output wire [31:0] passed,
  output wire [31:0] failed
);
  localparam [N-1:0] ZERO_N = {N{1'b0}};
  localparam [N-1:0] ALL_N  = {N{1'b1}};
  localparam [N-1:0] ONE_N  = {{(N-1){1'b0}}, 1'b1};

  reg          rst_n = 1'b0;
  reg  [N-1:0] req   = {N{1'b0}};
  wire [N-1:0] grant;

  rr_arbiter #(.N(N)) dut (
    .clk   (clk),
    .rst_n (rst_n),
    .req   (req),
    .grant (grant)
  );

  // ---------------- reference pointer model ----------------
  integer     m_ptr;
  integer     m_win;
  integer     m_off;
  integer     m_idx;
  reg [N-1:0] m_grant;
  reg [N-1:0] m_bits;
  reg         m_wrapped = 1'b0;

  always @* begin
    m_grant = ZERO_N;
    m_win   = -1;
    for (m_off = 0; m_off < N; m_off = m_off + 1) begin
      m_idx  = (m_ptr + m_off) % N;
      m_bits = req >> m_idx;
      if ((m_win < 0) && m_bits[0]) begin
        m_win   = m_idx;
        m_grant = ONE_N << m_idx;
      end
    end
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      m_ptr <= 0;
    end else if (m_win >= 0) begin
      m_ptr <= (m_win + 1) % N;
      if (m_win == N - 1) m_wrapped <= 1'b1;
    end
  end

  // Checking starts once a reset edge has been seen.
  reg armed = 1'b0;
  always @(posedge clk) begin
    if (!rst_n) armed <= 1'b1;
  end

  // ---------------- per-requester wait counters ----------------
  wire [N-1:0] viol;
  wire [N-1:0] maxw;
  genvar gi;
  generate
    for (gi = 0; gi < N; gi = gi + 1) begin : g_req
      integer wcnt    = 0;
      reg     hit_max = 1'b0;
      always @(posedge clk) begin
        if (!rst_n || !req[gi] || grant[gi]) wcnt <= 0;
        else                                 wcnt <= wcnt + 1;
        if (armed && rst_n && req[gi] && grant[gi] && (wcnt == N - 1))
          hit_max <= 1'b1;
      end
      // An N-th consecutive refused cycle is a fairness violation.
      assign viol[gi] = armed & rst_n & req[gi] & ~grant[gi] & (wcnt >= N - 1);
      assign maxw[gi] = hit_max;
    end
  endgenerate

  // ---------------- checks and coverage ----------------
  reg [31:0]  n_pass       = 32'd0;
  reg [31:0]  n_fail       = 32'd0;
  reg         stim_done    = 1'b0;
  reg         done_r       = 1'b0;
  reg         cov_none     = 1'b0;
  reg         cov_all      = 1'b0;
  reg         cov_held     = 1'b0;
  reg         cov_rst      = 1'b0;
  reg         seen_traffic = 1'b0;
  reg [N-1:0] cov_alone    = {N{1'b0}};
  reg [N-1:0] prev_req     = {N{1'b0}};
  reg [N-1:0] prev_grant   = {N{1'b0}};
  reg         prev_rst     = 1'b0;
  reg [N-1:0] held;
  integer     all_run      = 0;

  always @(negedge clk) begin
    if (armed) begin
      // grant against the reference model
      if (grant === m_grant) begin
        n_pass = n_pass + 32'd1;
      end else begin
        $error("rr_arbiter N=%0d t=%0t: req=%b grant=%b, model expects %b (model pointer %0d)",
               N, $time, req, grant, m_grant, m_ptr);
        n_fail = n_fail + 32'd1;
      end
      // one-hot or zero, only to requesters, work conserving
      if (((grant & (grant - ONE_N)) == ZERO_N) &&
          ((grant & ~req) == ZERO_N) &&
          ((req != ZERO_N) == (grant != ZERO_N))) begin
        n_pass = n_pass + 32'd1;
      end else begin
        $error("rr_arbiter N=%0d t=%0t: grant property broken, req=%b grant=%b",
               N, $time, req, grant);
        n_fail = n_fail + 32'd1;
      end
      // fairness bound
      if (viol == ZERO_N) begin
        n_pass = n_pass + 32'd1;
      end else begin
        $error("rr_arbiter N=%0d t=%0t: requesters %b refused after waiting N-1 cycles",
               N, $time, viol);
        n_fail = n_fail + 32'd1;
      end

      // coverage
      if (rst_n && (req == ZERO_N)) cov_none = 1'b1;
      if (rst_n && (req != ZERO_N) && ((req & (req - ONE_N)) == ZERO_N))
        cov_alone = cov_alone | req;
      if (rst_n && (req == ALL_N)) all_run = all_run + 1;
      else                         all_run = 0;
      if (all_run >= 2 * N) cov_all = 1'b1;
      held = req & prev_req & ~prev_grant;
      if (rst_n && prev_rst && (held != ZERO_N) && ((req ^ prev_req) != ZERO_N))
        cov_held = 1'b1;
      if (rst_n && (grant != ZERO_N)) seen_traffic = 1'b1;
      if (!rst_n && seen_traffic && (req != ZERO_N)) cov_rst = 1'b1;
      prev_req   = req;
      prev_grant = grant;
      prev_rst   = rst_n;
    end

    if (stim_done && !done_r) begin
      if (cov_none) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: no-request cycle not covered", N); n_fail = n_fail + 32'd1; end
      if (cov_alone == ALL_N) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: requester alone not covered for all, seen %b", N, cov_alone); n_fail = n_fail + 32'd1; end
      if (cov_all) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: everyone requesting not covered", N); n_fail = n_fail + 32'd1; end
      if (cov_held) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: held request among changing others not covered", N); n_fail = n_fail + 32'd1; end
      if (maxw != ZERO_N) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: longest fair wait (N-1) not covered", N); n_fail = n_fail + 32'd1; end
      if (cov_rst) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: reset during traffic not covered", N); n_fail = n_fail + 32'd1; end
      if (m_wrapped) n_pass = n_pass + 32'd1;
      else begin $error("rr_arbiter N=%0d: pointer wrap not covered", N); n_fail = n_fail + 32'd1; end
      done_r = 1'b1;
    end
  end

  assign done   = done_r;
  assign passed = n_pass;
  assign failed = n_fail;

  // ---------------- stimulus ----------------
  reg [31:0] rng;
  integer    k;
  integer    h;
  integer    c;

  function [31:0] xorshift32;
    input [31:0] v;
    reg   [31:0] t;
    begin
      t = v ^ (v << 13);
      t = t ^ (t >> 17);
      t = t ^ (t << 5);
      xorshift32 = t;
    end
  endfunction

  // Apply r just after a rising edge and hold it for one cycle.
  task cycle_with;
    input [N-1:0] r;
    begin
      req = r;
      @(posedge clk);
      #1;
    end
  endtask

  initial begin
    rng = (SEED == 32'd0) ? 32'h0000_0001 : SEED;
    @(posedge clk);
    #1;
    // Reset with requests: grant follows req, pointer stays 0.
    rst_n = 1'b0;
    cycle_with(ALL_N);
    cycle_with(ALL_N);
    // Release with everyone requesting: strict rotation 0..N-1, last waits N-1.
    rst_n = 1'b1;
    for (c = 0; c < 3 * N; c = c + 1) cycle_with(ALL_N);
    // No requests.
    cycle_with(ZERO_N);
    cycle_with(ZERO_N);
    // Each requester alone.
    for (k = 0; k < N; k = k + 1) begin
      cycle_with(ONE_N << k);
      cycle_with(ONE_N << k);
    end
    // A held request among changing others.
    for (h = 0; h < N; h = h + 1) begin
      for (c = 0; c < 6 * N; c = c + 1) begin
        rng = xorshift32(rng);
        cycle_with(rng[N-1:0] | (ONE_N << h));
      end
    end
    // Random subsets, drops and re-raises, idle cycles.
    for (c = 0; c < 400; c = c + 1) begin
      rng = xorshift32(rng);
      if (rng[31:29] == 3'b000) cycle_with(ZERO_N);
      else                      cycle_with(rng[N-1:0]);
    end
    // Reset during traffic.
    rst_n = 1'b0;
    for (c = 0; c < 2; c = c + 1) begin
      rng = xorshift32(rng);
      cycle_with(rng[N-1:0] | ONE_N);
    end
    rst_n = 1'b1;
    for (c = 0; c < 2 * N; c = c + 1) cycle_with(ALL_N);
    for (c = 0; c < 100; c = c + 1) begin
      rng = xorshift32(rng);
      cycle_with(rng[N-1:0]);
    end
    cycle_with(ZERO_N);
    stim_done = 1'b1;
  end
endmodule
